// bring in Verus’s standard prelude
use vstd::prelude::*;
use builtin::*;

verus! {

/// Returns 1.0 exactly when i == j, otherwise 0.0.
fn diag_val(i: isize, j: isize) -> f64
    ensures
        // postcondition: result = 1.0 if and only if i==j
        result == if i == j { 1.0 } else { 0.0 }
{
    if i == j {
        1.0
    } else {
        0.0
    }
}

/// Builds the n×n identity matrix as a Vec<Vec<f64>>.
/// 
/// Ensures:
///  1) the outer vector has length n,
///  2) each inner vector has length n,
///  3) the (i,j) entry is 1.0 exactly when i==j, else 0.0.
fn identity(n: usize) -> Vec<Vec<f64>>
    ensures
        // the matrix has n rows
        result.len() == n,
    ensures
        // each row has length n
        forall|i: usize| i < n ==> result[i].len() == n,
    ensures
        // each entry is 1.0 on the diagonal, 0.0 off it
        forall|i: usize, j: usize| i < n && j < n
            ==> result[i][j] == if i == j { 1.0 } else { 0.0 }
{
    (0..n)
        .map(|i| {
            (0..n)
                .map(|j| diag_val(i as isize, j as isize))
                .collect()
        })
        .collect()
}

} // end verus!  

fn main() {
    // Examples
    let id0 = identity(0);
    assert_eq!(id0, vec![]);

    let id1 = identity(1);
    assert_eq!(id1, vec![vec![1.0]]);

    let id3 = identity(3);
    assert_eq!(
        id3,
        vec![
            vec![1.0, 0.0, 0.0],
            vec![0.0, 1.0, 0.0],
            vec![0.0, 0.0, 1.0],
        ]
    );
}